import { Box, Flex, Text } from "@chakra-ui/react";
import React, { forwardRef } from "react";
import { Icon } from "../../../Icon";
import { Dumbbell } from "../../../Icon/icons";
import { useInspectorStore } from "../../../store";
import { type ConversationEvent, type ConversationEventAction } from "../../../types";
import { ConversationEventActionButton } from "../../ConversationEventActionButton";
import { useConversationLogSx } from "../useConversationLogSx";
import { skillEventVerbs } from "./skillEventLabel";

interface SkillEventProps {
  event: ConversationEvent;
  isSelected: boolean;
  conversationEventActions?: ConversationEventAction[];
  onClick?: React.MouseEventHandler<HTMLDivElement>;
  onKeyDown?: (event: React.KeyboardEvent<HTMLDivElement>) => void;
}

export const SkillEvent = forwardRef<HTMLDivElement | null, SkillEventProps>(
  (props: SkillEventProps, ref) => {
    const {
      event,
      isSelected = false,
      conversationEventActions,
      onClick,
      onKeyDown,
      ...otherProps
    } = props;
    const { hoverableContainerSx, baseMessageSx, iconSx } = useConversationLogSx(isSelected);
    const skillCatalog = useInspectorStore((state) => state.skillCatalog);
    const [isHovered, setIsHovered] = React.useState(false);
    const skill = event.skillId ? skillCatalog?.[event.skillId] : undefined;
    const skillName = skill?.name ?? skill?.id ?? event.skillId ?? "skill";
    const verb = skillEventVerbs[event.conversationEventType] ?? "";

    return (
      <Flex
        ref={ref}
        tabIndex={0}
        role="button"
        position="relative"
        cursor="pointer"
        css={hoverableContainerSx}
        onMouseEnter={() => setIsHovered(true)}
        onMouseLeave={() => setIsHovered(false)}
        onClick={onClick}
        onKeyDown={onKeyDown}
        {...otherProps}
      >
        {isHovered && (
          <ConversationEventActionButton event={event} actions={conversationEventActions} />
        )}
        <Box css={baseMessageSx}>
          <Icon icon={Dumbbell} style={iconSx} />
          <Text textStyle="xs" lineClamp={2} wordBreak="break-all">
            <Text as="span" fontWeight="medium">
              {skillName}
            </Text>{" "}
            skill {verb}
          </Text>
        </Box>
      </Flex>
    );
  },
);

SkillEvent.displayName = "SkillEvent";
